package com.nigson.commerce.market;
import java.util.*;
import java.time.Clock;
import org.springframework.jdbc.core.JdbcTemplate;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
/** Own-schema local statements only. No creation or book assignment activates selling. */
public final class JdbcMarketRepository implements MarketRepository {
 private final JdbcTemplate jdbc;private final Clock clock;public JdbcMarketRepository(JdbcTemplate jdbc,Clock clock){this.jdbc=jdbc;this.clock=clock;}
 private void currency(String code){var rows=jdbc.query("SELECT minor_unit,active FROM commerce.currency WHERE code=? FOR SHARE",(r,n)->Map.entry(r.getInt(1),r.getBoolean(2)),code);if(rows.size()!=1||!rows.getFirst().getValue()||(code.equals("NGN")&&rows.getFirst().getKey()!=2))throw MarketValues.rule();}
 public MarketValues.Market create(MarketValues.Create input,String actor){if(input.code().equals("NG")&&!input.currency().equals("NGN"))throw MarketValues.rule();currency(input.currency());UUID id=EventCodec.uuid7(clock.instant());try{jdbc.update("INSERT INTO commerce.market(id,created_by,updated_by,code,name,currency_code,enabled,policy_revision,tax_policy) VALUES (?,?,?,?,?,?,false,1,'{}'::jsonb)",id,actor,actor,input.code(),input.name(),input.currency());}catch(org.springframework.dao.DuplicateKeyException conflict){throw new Problem.Failure(ProblemCode.CONFLICT);}return find(id,false);}
 public MarketValues.Market find(UUID id,boolean lock){var rows=jdbc.query("SELECT id,code,name,currency_code,enabled,tax_policy::text,returns_policy_revision,retail_price_book_id,policy_revision,version FROM commerce.market WHERE id=?"+(lock?" FOR UPDATE":""),(r,n)->new MarketValues.Market(r.getObject(1,UUID.class),r.getString(2),r.getString(3),r.getString(4),r.getBoolean(5),List.of(),EventCodec.JSON.readTree(r.getString(6)),r.getString(7),r.getObject(8,UUID.class),r.getLong(9),r.getLong(10)),id);if(rows.isEmpty())throw new Problem.Failure(ProblemCode.NOT_FOUND);var v=rows.getFirst();var destinations=jdbc.query("SELECT country_code,address_rules::text,delivery_enabled FROM commerce.market_destination WHERE market_id=? ORDER BY country_code LIMIT 251",(r,n)->new MarketValues.Destination(r.getString(1),EventCodec.JSON.readTree(r.getString(2)),r.getBoolean(3)),id);if(destinations.size()>250)throw MarketValues.rule();return new MarketValues.Market(v.id(),v.code(),v.name(),v.currency(),v.enabled(),destinations,v.taxPolicy(),v.returnsPolicyRevision(),v.retailPriceBookId(),v.policyRevision(),v.version());}
 public MarketValues.Market book(UUID id,long expected,MarketValues.Book input,String actor){var before=find(id,true);if(before.version()!=expected)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);currency(before.currency());var valid=jdbc.query("SELECT id FROM commerce.price_book WHERE id=? AND active AND segment='RETAIL' AND currency_code=? AND effective_from<=? AND (effective_until IS NULL OR effective_until>?) FOR SHARE",(r,n)->r.getObject(1,UUID.class),input.priceBookId(),before.currency(),java.sql.Timestamp.from(clock.instant()),java.sql.Timestamp.from(clock.instant()));if(valid.isEmpty()||before.policyRevision()==Long.MAX_VALUE)throw MarketValues.rule();jdbc.update("UPDATE commerce.market SET retail_price_book_id=?,policy_revision=policy_revision+1,version=version+1,updated_by=?,updated_at=? WHERE id=?",input.priceBookId(),actor,java.sql.Timestamp.from(clock.instant()),id);return find(id,false);}
 public MarketValues.Market update(UUID id,long expected,MarketValues.Update input,String actor){
  var before=find(id,true);if(before.version()!=expected)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);
  if(input.enabled())throw MarketValues.rule(); // No approved tax, returns, route, price and provider evidence is configured.
  boolean safeDisable=before.enabled()&&!input.enabled()&&before.destinations().equals(input.destinations());
  if(input.destinations().stream().anyMatch(MarketValues.Destination::deliveryEnabled)&&!safeDisable)throw MarketValues.rule();
  if(before.code().equals("NG")&&!input.currency().equals("NGN"))throw MarketValues.rule();
  currency(input.currency());
  if(!before.currency().equals(input.currency())&&Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.sales_order WHERE market_id=?)",Boolean.class,id)))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);
  if(before.retailPriceBookId()!=null){var book=jdbc.query("SELECT id FROM commerce.price_book WHERE id=? AND currency_code=? FOR SHARE",(r,n)->r.getObject(1,UUID.class),before.retailPriceBookId(),input.currency());if(book.isEmpty())throw MarketValues.rule();}
  boolean policyChanged=!before.currency().equals(input.currency())||before.enabled()!=input.enabled()||!before.destinations().equals(input.destinations())||!before.taxPolicy().equals(input.taxPolicy())||!Objects.equals(before.returnsPolicyRevision(),input.returnsPolicyRevision());
  boolean changed=policyChanged||!before.name().equals(input.name());if(!changed)return before;
  if(before.version()==Long.MAX_VALUE||policyChanged&&before.policyRevision()==Long.MAX_VALUE)throw MarketValues.rule();
  jdbc.update("UPDATE commerce.market SET name=?,currency_code=?,enabled=?,tax_policy=?::jsonb,returns_policy_revision=?,policy_revision=policy_revision+?,version=version+1,updated_by=?,updated_at=? WHERE id=?",input.name(),input.currency(),input.enabled(),EventCodec.JSON.writeValueAsString(input.taxPolicy()),input.returnsPolicyRevision(),policyChanged?1:0,actor,java.sql.Timestamp.from(clock.instant()),id);
  if(!before.destinations().equals(input.destinations())){jdbc.update("DELETE FROM commerce.market_destination WHERE market_id=?",id);for(var destination:input.destinations())jdbc.update("INSERT INTO commerce.market_destination(id,created_by,updated_by,market_id,country_code,address_rules,delivery_enabled) VALUES (?,?,?,?,?,?::jsonb,?)",EventCodec.uuid7(clock.instant()),actor,actor,id,destination.countryCode(),EventCodec.JSON.writeValueAsString(destination.addressRules()),destination.deliveryEnabled());}
  return find(id,false);
 }
 public void restriction(UUID product,UUID market,MarketValues.Eligibility input,String actor){var target=jdbc.query("SELECT id FROM commerce.market WHERE id=? FOR SHARE",(r,n)->r.getObject(1,UUID.class),market);if(target.isEmpty())throw new Problem.Failure(ProblemCode.NOT_FOUND);jdbc.update("INSERT INTO commerce.product_market_eligibility(id,created_by,updated_by,product_id,market_id,eligible,reason) VALUES (?,?,?,?,?,?,?) ON CONFLICT(product_id,market_id) DO UPDATE SET eligible=EXCLUDED.eligible,reason=EXCLUDED.reason,version=commerce.product_market_eligibility.version+1,updated_by=EXCLUDED.updated_by,updated_at=now()",EventCodec.uuid7(clock.instant()),actor,actor,product,market,input.eligible(),input.reason());}
 public List<MarketValues.PublicMarket> publicMarkets(){var markets=jdbc.query("SELECT m.id,m.code,m.currency_code,m.policy_revision FROM commerce.market m JOIN commerce.currency c ON c.code=m.currency_code WHERE m.enabled AND c.active AND m.code='NG' AND c.code='NGN' AND c.minor_unit=2 AND EXISTS(SELECT 1 FROM commerce.market_destination d WHERE d.market_id=m.id AND d.country_code='NG' AND d.delivery_enabled) ORDER BY m.code LIMIT 101",(r,n)->new MarketValues.PublicMarket(r.getObject(1,UUID.class),r.getString(2),r.getString(3),List.of("NG"),r.getLong(4)));if(markets.size()>100)throw MarketValues.rule();return markets.stream().filter(m->{var v=find(m.id(),false);try{MarketValues.tax(v.taxPolicy());if(v.returnsPolicyRevision()==null||v.returnsPolicyRevision().isBlank()||v.retailPriceBookId()==null)return false;var d=v.destinations().stream().filter(x->x.countryCode().equals("NG")&&x.deliveryEnabled()).findFirst();if(d.isEmpty())return false;MarketValues.address(d.get().addressRules());return Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.price_book WHERE id=? AND active AND segment='RETAIL' AND currency_code='NGN' AND effective_from<=? AND (effective_until IS NULL OR effective_until>?))",Boolean.class,v.retailPriceBookId(),java.sql.Timestamp.from(clock.instant()),java.sql.Timestamp.from(clock.instant())));}catch(com.nigson.shared.problem.Problem.Failure invalid){return false;}}).toList();}
}
